<?php

namespace Database\Seeders;

use App\Domains\Guides\Models\Guide;
use Illuminate\Database\Seeder;

/**
 * EXPA content expansion V6: fills gaps across existing product categories.
 * Content is original guidance linked to official sources; production remains in review.
 */
class OfficialContentV6Seeder extends Seeder
{
    private const VERIFIED_AT = '2026-10-10';

    public function run(): void
    {
        foreach ($this->items() as $index => $item) {
            $guide = Guide::updateOrCreate(
                ['slug' => $item['slug']],
                [
                    'category' => $item['category'],
                    'italian_term' => $item['italian_term'],
                    'sort_order' => 3000 + ($index * 10),
                    'source_name' => $item['source_name'],
                    'source_url' => $item['source_url'],
                    'source_type' => 'official',
                    'last_verified_at' => self::VERIFIED_AT,
                ]
            );

            $guide->setTranslations($item['translations']);
            $local = app()->environment('local', 'testing');
            $guide->forceFill([
                'status' => $local ? 'published' : 'review',
                'published_at' => $local ? ($guide->published_at ?? now()) : null,
            ])->save();
        }
    }

    private function tr(array $ar, array $en, array $it): array
    {
        return ['ar' => $ar, 'en' => $en, 'it' => $it];
    }

    private function guide(string $title, string $summary, string $what, string $who, array $docs, array $steps, string $where, string $cost, string $time, string $body): array
    {
        return compact('title', 'summary', 'what', 'who', 'docs', 'steps', 'where', 'cost', 'time', 'body');
    }

