                'translations' => $this->tr(
                    $this->guide('اختيار طبيب الأسرة في إيطاليا', 'ما الذي تفعله بعد التسجيل الصحي للعثور على طبيب الأسرة المناسب في منطقتك.', 'Medico di medicina generale أو medico di base هو طبيب الرعاية الأولية للمسجلين المؤهلين في SSN. الاختيار والتغيير يتمان وفق الإجراءات المحلية وتوافر الأطباء.', 'المسجلون في SSN الذين يحتاجون إلى اختيار طبيب أو تغييره أو معرفة كيفية الوصول إلى الخدمات المحلية.', ['Codice Fiscale أو Tessera Sanitaria', 'وثيقة هوية', 'بيانات التسجيل في SSN', 'عنوان الإقامة أو السكن إذا طُلب'], [['تحقق من تسجيلك في SSN', 'إذا لم يكن التسجيل مكتملًا، اتبع دليل التسجيل أولًا.'], ['افتح موقع ASL المحلي', 'ابحث عن قائمة الأطباء المتاحين وطريقة الاختيار أو التغيير.'], ['قدّم الطلب بالقناة المحددة', 'قد تكون الخدمة عبر الإنترنت أو في المكتب، حسب المنطقة.'], ['احفظ بيانات الطبيب', 'تحقق من ساعات الاستقبال وطريقة طلب الزيارة والوصفات والإحالات.']], 'ASL المختصة بمنطقتك؛ في روما استخدم خدمات ASL Roma التابعة لمنطقة سكنك.', 'اختيار الطبيب ضمن الخدمة العامة لا يعني أن كل خدمة صحية مجانية؛ قد تطبق قواعد التذاكر الصحية على بعض الخدمات.', 'يعتمد الاختيار على توفر الأطباء والإجراء المحلي.', 'في حالة الطوارئ لا تنتظر موعد طبيب الأسرة؛ استخدم خدمات الطوارئ المناسبة. هذا الدليل إداري وليس تشخيصًا طبيًا.'),
                    $this->guide('Choosing a family doctor in Italy', 'What to do after SSN registration to find an available primary-care doctor in your area.', 'A medico di medicina generale (medico di base) provides primary care to eligible SSN members. Selection and changes follow local procedures and doctor availability.', 'People registered with the SSN who need to select or change a doctor or understand local access.', ['Codice Fiscale or Tessera Sanitaria', 'Identity document', 'SSN registration details', 'Residence or domicile information if requested'], [['Confirm SSN registration', 'If registration is incomplete, follow the registration guide first.'], ['Open your local ASL website', 'Find the available doctor list and the selection or change procedure.'], ['Submit through the stated channel', 'The service may be online or in person depending on the area.'], ['Save the doctor’s details', 'Check office hours and how to request visits, prescriptions and referrals.']], 'The ASL serving your area; in Rome, use the ASL Roma services for your district.', 'Primary-care selection does not mean every healthcare service is free; co-payments may apply to some services.', 'Selection depends on local procedure and doctor availability.', 'For emergencies, do not wait for a family-doctor appointment; use the appropriate emergency service. This is administrative guidance, not a diagnosis.'),
                    $this->guide('Scegliere il medico di base in Italia', 'Come trovare un medico disponibile dopo l’iscrizione al SSN.', 'Il medico di medicina generale assiste gli iscritti aventi diritto al SSN. Scelta e cambio seguono procedure locali e disponibilità dei medici.', 'Persone iscritte al SSN che devono scegliere o cambiare medico o capire come accedere ai servizi.', ['Codice Fiscale o Tessera Sanitaria', 'Documento d’identità', 'Dati di iscrizione al SSN', 'Residenza o domicilio, se richiesti'], [['Verifica l’iscrizione al SSN', 'Se non è completa, segui prima la procedura d’iscrizione.'], ['Consulta il sito della ASL', 'Cerca elenco dei medici e modalità di scelta o cambio.'], ['Invia la richiesta', 'Il servizio può essere online o allo sportello secondo la zona.'], ['Conserva i riferimenti', 'Controlla orari e modalità per visite, ricette e impegnative.']], 'ASL competente; a Roma usa i servizi della ASL Roma della tua zona.', 'La scelta del medico non rende gratuite tutte le prestazioni: per alcuni servizi possono essere previsti ticket.', 'Dipende dalla procedura locale e dalla disponibilità.', 'In emergenza non attendere l’appuntamento con il medico di base. Questa guida è amministrativa, non una diagnosi.')
